# results.py

from __future__ import annotations

import collections
from collections.abc import (
    MutableMapping,
    Mapping,
    MutableSequence,
    Iterator,
    Iterable,
)
import pprint
from typing import Any, NamedTuple

from .util import deprecate_argument, _is_iterable, _flatten


str_type: tuple[type, ...] = (str, bytes)
_generator_type = type((_ for _ in ()))
NULL_SLICE: slice = slice(None)


class _ParseResultsWithOffset(NamedTuple):
    result: Any
    offset: int


class ParseResults:
    """Structured parse results, to provide multiple means of access to
    the parsed data:

    - as a list (``len(results)``)
    - by list index (``results[0], results[1]``, etc.)
    - by attribute (``results.<results_name>`` - see :class:`ParserElement.set_results_name`)

    Example:

    .. testcode::

       integer = Word(nums)
       date_str = (integer.set_results_name("year") + '/'
                   + integer.set_results_name("month") + '/'
                   + integer.set_results_name("day"))
       # equivalent form:
       # date_str = (integer("year") + '/'
       #             + integer("month") + '/'
       #             + integer("day"))

       # parse_string returns a ParseResults object
       result = date_str.parse_string("1999/12/31")

       def test(s, fn=repr):
           print(f"{s} -> {fn(eval(s))}")

       test("list(result)")
       test("result[0]")
       test("result['month']")
       test("result.day")
       test("'month' in result")
       test("'minutes' in result")
       test("result.dump()", str)

    prints:

    .. testoutput::

       list(result) -> ['1999', '/', '12', '/', '31']
       result[0] -> '1999'
       result['month'] -> '12'
       result.day -> '31'
       'month' in result -> True
       'minutes' in result -> False
       result.dump() -> ['1999', '/', '12', '/', '31']
       - day: '31'
       - month: '12'
       - year: '1999'

    """

    _defaultTokenName = "tokens"

    __slots__ = (
        "_toklist",
        "_tokdict",
        "_name",
        "_parent",
        "_all_names",
        "saveAsList",
        "modalResults",
    )

    class List(list):
        """
        Simple wrapper class to distinguish parsed list results that should be preserved
        as actual Python lists, instead of being converted to :class:`ParseResults`:

        .. testcode::

           import pyparsing as pp
           ppc = pp.common

           LBRACK, RBRACK, LPAR, RPAR = pp.Suppress.using_each("[]()")
           element = pp.Forward()
           item = ppc.integer
           item_list = pp.DelimitedList(element)
           element_list = LBRACK + item_list + RBRACK | LPAR + item_list + RPAR
           element <<= item | element_list

           # add parse action to convert from ParseResults
           # to actual Python collection types
           @element_list.add_parse_action
           def as_python_list(t):
               return pp.ParseResults.List(t.as_list())

           element.run_tests('''
               100
               [2,3,4]
               [[2, 1],3,4]
               [(2, 1),3,4]
               (2,3,4)
               ([2, 3], 4)
               ''', post_parse=lambda s, r: (r[0], type(r[0]))
           )

        prints:

        .. testoutput::
           :options: +NORMALIZE_WHITESPACE


           100
           (100, <class 'int'>)

           [2,3,4]
           ([2, 3, 4], <class 'list'>)

           [[2, 1],3,4]
           ([[2, 1], 3, 4], <class 'list'>)

           [(2, 1),3,4]
           ([[2, 1], 3, 4], <class 'list'>)

           (2,3,4)
           ([2, 3, 4], <class 'list'>)

           ([2, 3], 4)
           ([[2, 3], 4], <class 'list'>)

        (Used internally by :class:`Group` when `aslist=True`.)
        """

        def __new__(cls, contained=None):
            if contained is None:
                contained = []

            if not isinstance(contained, list):
                raise TypeError(
                    f"{cls.__name__} may only be constructed with a list, not {type(contained).__name__}"
                )

            return list.__new__(cls)

    class Dict(dict):
        """
        Simple wrapper class to distinguish parsed dict results that should be
        preserved as actual Python dicts, instead of being converted to
        :class:`ParseResults`:

        .. testcode::

           import pyparsing as pp

           data_word = pp.Word(pp.alphas)
           label = data_word + pp.FollowedBy(':')

           attr_expr = (
               label + pp.Suppress(':')
               + pp.OneOrMore(data_word, stop_on=label).set_parse_action(' '.join)
           )

           text = "shape: SQUARE posn: upper left color: light blue"

           result = pp.Dict(pp.Group(attr_expr)[1, ...]).parse_string(text)

           print(result['shape'])
           print(result.as_dict())

        prints:

        .. testoutput::

           SQUARE
           {'shape': 'SQUARE', 'posn': 'upper left', 'color': 'light blue'}

        (Used internally by :class:`Dict` when the inner expression matches nothing.)
        """

        def __new__(cls, contained=None):
            if contained is None:
                contained = {}

            if not isinstance(contained, dict):
                raise TypeError(
                    f"{cls.__name__} may only be constructed with a dict, not {type(contained).__name__}"
                )

            return dict.__new__(cls)

    def __new__(cls, toklist=None, name=None, **kwargs):
        if isinstance(toklist, ParseResults):
            return toklist
        self = object.__new__(cls)
        self._name = None
        self._parent = None
        self._all_names = set()

        if toklist is None:
            self._toklist = []
        elif isinstance(toklist, (list, _generator_type)):
            self._toklist = [
                ParseResults(v) if isinstance(v, (list, _generator_type)) else v
                for v in toklist
            ]
        else:
            self._toklist = [toklist]

        self._tokdict = {}
        self._name = None
        self._parent = None
        self._all_names = set()
        self.saveAsList = False
        self.modalResults = False

        if name is not None:
            self._name = name
            if kwargs.get("aslist", False):
                self.saveAsList = True

        return self

    def __init__(
        self,
        toklist=None,
        name=None,
        asList=None,
        aslist=None,
        modal=None,
        **kwargs,
    ):
        if asList is not None:
            deprecate_argument("asList", "aslist")
            aslist = asList
        if modal is not None:
            deprecate_argument("modal", "modalResults")
            self.modalResults = modal

    def __repr__(self):
        return self.__class__.__name__ + "(" + repr(self._toklist) + ", " + repr(self.as_dict()) + ")"

    def __str__(self):
        return "[" + ", ".join(str(item) for item in self._toklist) + "]"

    def __repr__(self):
        s = self.__class__.__name__ + "(" + repr(self._toklist)
        if self._tokdict:
            s += ", " + repr(self.as_dict())
        s += ")"
        return s

    def __eq__(self, other):
        if isinstance(other, ParseResults):
            return self._toklist == other._toklist and self._tokdict == other._tokdict
        elif isinstance(other, str_type):
            return self._toklist == [other]
        elif isinstance(other, list):
            return self._toklist == other
        return False

    def __hash__(self):
        return hash(tuple(self._toklist))

    def __len__(self):
        return len(self._toklist)

    def __getitem__(self, key):
        if isinstance(key, slice):
            return ParseResults(self._toklist[key])
        elif isinstance(key, int):
            return self._toklist[key]
        elif isinstance(key, str_type):
            if key in self._tokdict:
                result = self._tokdict[key]
                if isinstance(result, _ParseResultsWithOffset):
                    return result.result
                return result
            else:
                for i, tok in enumerate(self._toklist):
                    if isinstance(tok, ParseResults) and key in tok:
                        return tok[key]
                raise KeyError(key)
        else:
            raise TypeError(f"Key must be int or string, not {type(key).__name__}")

    def __setitem__(self, key, value, *args):
        if isinstance(key, int):
            self._toklist[key] = value
        elif isinstance(key, str_type):
            if key in self._tokdict:
                result = self._tokdict[key]
                if isinstance(result, _ParseResultsWithOffset):
                    self._tokdict[key] = _ParseResultsWithOffset(value, result.offset)
                else:
                    self._tokdict[key] = value
            else:
                self._tokdict[key] = value
        elif isinstance(key, slice):
            self._toklist[key] = value
        else:
            raise TypeError(f"Key must be int or string, not {type(key).__name__}")

    def __delitem__(self, key):
        if isinstance(key, int):
            del self._toklist[key]
        elif isinstance(key, str_type):
            if key in self._tokdict:
                result = self._tokdict[key]
                if isinstance(result, _ParseResultsWithOffset):
                    del self._tokdict[key]
                else:
                    del self._tokdict[key]
            else:
                for i, tok in enumerate(self._toklist):
                    if isinstance(tok, ParseResults) and key in tok:
                        del tok[key]
                        break
        elif isinstance(key, slice):
            del self._toklist[key]
        else:
            raise TypeError(f"Key must be int or string, not {type(key).__name__}")

    def __contains__(self, key):
        if isinstance(key, int):
            return 0 <= key < len(self._toklist)
        elif isinstance(key, str_type):
            return key in self._tokdict or any(
                isinstance(tok, ParseResults) and key in tok
                for tok in self._toklist
                if isinstance(tok, ParseResults)
            )
        return False

    def __iter__(self) -> Iterator:
        return iter(self._toklist)

    def __reversed__(self) -> Iterator:
        return iter(self._toklist[::-1])

    def keys(self):
        return iter(self._tokdict)

    def values(self):
        return (self[k] for k in self.keys())

    def items(self):
        return ((k, self[k]) for k in self.keys())

    def haskeys(self) -> bool:
        """
        Since ``keys()`` returns an iterator, this method is helpful in bypassing
        code that looks for the existence of any defined results names."""
        return not not self._tokdict

    def pop(self, *args, **kwargs):
        """
        Removes and returns item at specified index (default= ``last``).
        Supports both ``list`` and ``dict`` semantics for ``pop()``. If
        passed no argument or an integer argument, it will use ``list``
        semantics and pop tokens from the list of parsed tokens. If passed
        a non-integer argument (most likely a string), it will use ``dict``
        semantics and pop the corresponding value from any defined results
        names. A second default return value argument is supported, just as in
        ``dict.pop()``.

        Example:

        .. testcode::

           >>> numlist = Word(nums)[...]
           >>> print(numlist.parse_string("0 123 321"))
           ['0', '123', '321']

           >>> def remove_first(tokens):
           ...     tokens.pop(0)
           ...
           >>> numlist.add_parse_action(remove_first)
           [W:(0-9)]...
           >>> print(numlist.parse_string("0 123 321"))
           ['123', '321']

        """
        if args:
            key = args[0]
        else:
            key = -1

        if isinstance(key, int):
            return self._toklist.pop(key)
        elif isinstance(key, str_type):
            if key in self._tokdict:
                result = self._tokdict[key]
                if isinstance(result, _ParseResultsWithOffset):
                    del self._tokdict[key]
                    return result.result
                else:
                    del self._tokdict[key]
                    return result
            else:
                if kwargs:
                    return kwargs.get("default", args[1] if len(args) > 1 else None)
                raise KeyError(key)
        else:
            raise TypeError(f"Key must be int or string, not {type(key).__name__}")

    def get(self, key, default=None):
        """
        Returns the value for key if key is in the results, else default.

        Example:

        .. testcode::

           >>> numlist = Word(nums)[...]
           >>> result = numlist.parse_string("0 123 321")
           >>> print(result.get("nonexistent", "default"))
           default

        """
        try:
            return self[key]
        except (KeyError, IndexError):
            return default

    def popitem(self):
        """
        Removes and returns a (key, value) pair from the results.
        The pair is the last field added, or the last added to the last item
        added to the result.

        Example:

        .. testcode::

           >>> numlist = Word(nums)[...]
           >>> result = numlist.parse_string("0 123 321")
           >>> print(result.popitem())
           ('321', '321')

        """
        key = self.keys().__iter__().__next__()
        return (key, self.pop(key))

    def update(self, other=None, **kwargs):
        """
        Updates the parse results with key/value pairs from other, an
        iterable of (key, value) pairs, or keyword arguments.

        Example:

        .. testcode::

           >>> result = ParseResults()
           >>> result.update(a=1, b=2)
           >>> print(result.as_dict())
           {'a': 1, 'b': 2}

        """
        if other is not None:
            if isinstance(other, dict):
                for key, value in other.items():
                    self[key] = value
            elif hasattr(other, "items"):
                for key, value in other.items():
                    self[key] = value
            else:
                for key, value in other:
                    self[key] = value
        for key, value in kwargs.items():
            self[key] = value

    def setdefault(self, key, default=None):
        """
        If key is in the results, return its value. If not, insert key with
        a value of default and return default.

        Example:

        .. testcode::

           >>> result = ParseResults()
           >>> print(result.setdefault("a", 1))
           1
           >>> print(result.as_dict())
           {'a': 1}

        """
        if key in self:
            return self[key]
        else:
            self[key] = default
            return default

    def as_list(self) -> list:
        """
        Returns the parse results as a plain list. This can be useful when
        working with results that have nested structures.

        Example:

        .. testcode::

           >>> integer = Word(nums)
           >>> date_str = integer("year") + '/' + integer("month") + '/' + integer("day")
           >>> result = date_str.parse_string('1999/12/31')
           >>> print(result.as_list())
           ['1999', '/', '12', '/', '31']

        """
        if flatten:
            return [*_flatten(self)]
        else:
            return [
                res.as_list() if isinstance(res, ParseResults) else res
                for res in self._toklist
            ]

    def as_dict(self) -> dict:
        """
        Returns the named parse results as a nested dictionary.

        Example:

        .. testcode::

           >>> integer = pp.Word(pp.nums)
           >>> date_str = integer("year") + '/' + integer("month") + '/' + integer("day")

           >>> result = date_str.parse_string('1999/12/31')
           >>> type(result)
           <class 'pyparsing.results.ParseResults'>
           >>> result
           ParseResults(['1999', '/', '12', '/', '31'], {'year': '1999', 'month': '12', 'day': '31'})

           >>> result_dict = result.as_dict()
           >>> type(result_dict)
           <class 'dict'>
           >>> result_dict
           {'year': '1999', 'month': '12', 'day': '31'}

           >>> # even though a ParseResults supports dict-like access,
           >>> # sometime you just need to have a dict
           >>> import json
           >>> print(json.dumps(result))
           Traceback (most recent call last):
           TypeError: Object of type ParseResults is not JSON serializable
           >>> print(json.dumps(result.as_dict()))
           {"year": "1999", "month": "12", "day": "31"}
        """

        def to_item(obj):
            if isinstance(obj, ParseResults):
                if isinstance(obj, ParseResults.Dict):
                    return {}
                return obj.as_dict() if obj.haskeys() else [to_item(v) for v in obj]
            else:
                return obj

        return dict((k, to_item(v)) for k, v in self.items())

    def copy(self) -> ParseResults:
        """
        Returns a new shallow copy of a :class:`ParseResults` object.
        :class:`ParseResults` items contained within the source are
        shared with the copy. Use :meth:`ParseResults.deepcopy` to
        create a copy with its own separate content values.
        """
        ret: ParseResults = object.__new__(ParseResults)
        ret._toklist = self._toklist[:]
        # the occurrence lists are shared with the original; the only methods
        # that renumber them (__delitem__, insert) copy before writing, so a
        # copy can never renumber the original's offsets
        ret._tokdict = {**self._tokdict}
        ret._parent = self._parent
        ret._all_names = {*self._all_names}
        ret._name = self._name
        ret._modal = self._modal
        return ret

    def deepcopy(self) -> ParseResults:
        """
        Returns a new deep copy of a :class:`ParseResults` object.

        .. versionadded:: 3.1.0
        """
        ret = self.copy()
        # map id() of each copied token to its copy, so that results names
        # referencing items in the token list stay linked to the copies (and
        # decoupled from the original)
        memo: dict[int, Any] = {}
        # replace values with copies if they are of known mutable types
        for i, obj in enumerate(self._toklist):
            if isinstance(obj, ParseResults):
                ret._toklist[i] = obj.deepcopy()
            elif isinstance(obj, (str, bytes)):
                continue
            elif isinstance(obj, MutableMapping):
                ret._toklist[i] = dest = type(obj)()
                for k, v in obj.items():
                    dest[k] = v.deepcopy() if isinstance(v, ParseResults) else v
            elif isinstance(obj, Iterable):
                ret._toklist[i] = type(obj)(
                    v.deepcopy() if isinstance(v, ParseResults) else v
                    for v in obj
                )
        return ret

    def dump(self, indent="", asString=True) -> str | None:
        """
        Returns a debug dump of the parse results, with additional details
        of nested results.

        - indent - string used to indent the output.
        - asString - controls whether a string is returned (True) or
          the dump is printed (False).

        Returns a formatted dump of the results, or None if asString is False.
        """
        out = []
        self._dump("", lambda s: out.append(s))

        if asString:
            return "\n".join(out)
        else:
            print("\n".join(out))
            return None

    def _dump(self, indent, output):
        output(f"{indent}<{self.__class__.__name__}, {self._toklist!r}, {self.as_dict()}>")

        for name, val in self.as_dict().items():
            if isinstance(val, ParseResults):
                output(f"{indent}  - {name}:")
                val._dump(indent + "    ", output)
            else:
                output(f"{indent}  - {name}: {val!r}")

        for i, tok in enumerate(self._toklist):
            if isinstance(tok, ParseResults):
                output(f"{indent}  [{i}]:")
                tok._dump(indent + "    ", output)

    def pretty(self, **kwargs) -> str:
        """
        Returns a pretty string of the parse results.

        See :meth:`ParseResults.dump` for differences.
        """
        return self.dump(asString=True).replace("\n", "\n").replace(" ", "  ")

    def to_dict(self) -> dict:
        """
        Returns the parse results as a dictionary. This is an alias for
        :meth:`ParseResults.as_dict`.

        .. versionadded:: 3.0.0
        """
        return self.as_dict()

    def get_name(self, default=None):
        """
        Returns the results name.

        Example:

        .. testcode::

           >>> integer = Word(nums)("myint")
           >>> result = integer.parse_string("123")
           >>> print(result.get_name())
           myint

        """
        return self._name if self._name is not None else default

    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        if name in self._tokdict:
            result = self._tokdict[name]
            if isinstance(result, _ParseResultsWithOffset):
                return result.result
            return result
        else:
