            del self._tokdict[name]
        else:
            for tok in self._toklist:
                if isinstance(tok, ParseResults) and name in tok:
                    del tok[name]
                    break

    def __dir__(self):
        return dir(self.__class__) + list(self.keys())

    # dict-like interface

    def asDict(self) -> dict:
        """
        Returns the named parse results as a nested dictionary.

        .. deprecated:: 3.0.0
           Use :meth:`as_dict`
        """
        return self.as_dict()

    asdict = as_dict

    def asList(self) -> list:
        """
        Returns the parse results as a plain list.

        .. deprecated:: 3.0.0
           Use :meth:`as_list`
        """
        return self.as_list()

    aslist = as_list

    def getName(self, default=None):
        """
        Returns the results name.

        .. deprecated:: 3.0.0
